public class InvertiArray {
    public static void main(String[] args) {
        char[] a = {'p', 'i', 'p', 'p', 'o', '.'};

        // Inversione in-place con ciclo for
        for (int i = 0; i < a.length / 2; i++) {
            char temp = a[i];
            a[i] = a[a.length - 1 - i];
            a[a.length - 1 - i] = temp;
        }

        // Stampa dell'array invertito
        for (int i = 0; i < a.length; i++) {
            System.out.print(a[i]);
        }
    }
}
```

