public static double[][] moltiplicaPerScalare(double[][] matrice, double scalare) {
    int righe = matrice.length;
    int colonne = matrice[0].length;
    double[][] risultato = new double[righe][colonne];

    for (int i = 0; i < righe; i++) {
        for (int j = 0; j < colonne; j++) {
            risultato[i][j] = matrice[i][j] * scalare;
        }
    }
    return risultato;
}

public static long fattoriale(int n) {
    if (n <= 1) {
        return 1; // Caso base
    }
    return n * fattoriale(n - 1); // Passo ricorsivo
}
